    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
    override func startLoading() { client?.urlProtocol(self, didFailWithError: URLError(.notConnectedToInternet)) }
    override func stopLoading() {}
}

// Observation only, enabled exclusively for synthetic, network-blocked UI tests.
@MainActor
enum HubInputDiagnostics {
    private static var enabled = false
    private static var isFixtureSession: (@MainActor () -> Bool)?
    private static var observers: [NSObjectProtocol] = []
    static func enable(isFixtureSession: @escaping @MainActor () -> Bool) {
        let environment = ProcessInfo.processInfo.environment
        guard !enabled, environment["HUB_TESTING"] == "1", environment["HUB_UI_TESTING"] == "1", environment["HUB_INPUT_DIAGNOSTICS"] == "1", isFixtureSession() else { return }
        self.isFixtureSession = isFixtureSession
        enabled = true
        for name in [UITextField.textDidChangeNotification, UITextField.textDidBeginEditingNotification, UITextField.textDidEndEditingNotification,
                     UITextView.textDidChangeNotification, UITextView.textDidBeginEditingNotification, UITextView.textDidEndEditingNotification] {
            observers.append(NotificationCenter.default.addObserver(forName: name, object: nil, queue: .main) { notification in
                MainActor.assumeIsolated { nativeEvent(notification) }
            })
        }
    }
    private static func nativeEvent(_ notification: Notification) {
        guard enabled, isFixtureSession?() == true else { return }
        var ancestor = notification.object as? UIView
        var isComposer = false
        while let view = ancestor {
            if view.accessibilityIdentifier == "chat.composer" { isComposer = true; break }
            ancestor = view.superview
        }
        guard isComposer else { return }
        let input: any UITextInput
        let responder: UIResponder
        let text: String
        if let field = notification.object as? UITextField { guard !field.isSecureTextEntry else { return }; input = field; responder = field; text = field.text ?? "" }
        else if let view = notification.object as? UITextView { guard !view.isSecureTextEntry else { return }; input = view; responder = view; text = view.text ?? "" }
        else { return }
        func range(_ value: UITextRange?) -> [Int] {
            guard let value else { return [] }
            return [input.offset(from: input.beginningOfDocument, to: value.start), input.offset(from: input.beginningOfDocument, to: value.end)]
        }
        emit(["source":"uikit", "event":notification.name.rawValue, "object":String(describing: ObjectIdentifier(responder)),
              "first_responder":responder.isFirstResponder, "text":text, "selection":range(input.selectedTextRange), "marked":range(input.markedTextRange)])
    }
    static func model(old: String, new: String, scope: String, requestKey: String) {
        guard enabled, isFixtureSession?() == true else { return }
        emit(["source":"model", "old":old, "text":new, "scope":scope, "request_key":requestKey])
    }
    private static func emit(_ value: [String: Any]) {
        guard enabled, isFixtureSession?() == true else { return }
        var record = value; record["uptime"] = ProcessInfo.processInfo.systemUptime
        if let data = try? JSONSerialization.data(withJSONObject: record, options: [.sortedKeys]), let line = String(data: data, encoding: .utf8) { NSLog("HUB_INPUT_TRACE %@", line) }
    }
}
